 const pomerContent=[
  {title:'Rozdělení peněz v poměru',story:['Dva kamarádi si rozdělí společnou výhru 750 Kč v poměru 2 : 3.','Větší díl připadne tomu, komu náleží tři díly poměru.'],question:'Kolik korun činí větší díl výhry?',other:'Kolik korun činí menší díl?',paths:['Sečtu díly poměru (2+3=5), určím hodnotu jednoho dílu a vezmu tři díly.','Zapíšu větší podíl jako 3/5 z celé výhry 750 Kč.','Částku 750 Kč vydělím větším číslem poměru 3.'],valid:[0,1],explain:['Poměr má 2+3=5 dílů. Jeden díl je 750 ÷ 5 = 150 Kč a tři díly jsou 450 Kč.','Větší část tvoří tři z pěti stejných dílů: 750 × 3/5 = 450 Kč.','Číslo 3 není počet všech dílů; dělení jen třemi by nezachovalo poměr ani celkový součet.'],answer:450,unit:'Kč',check:'Menší díl 300 Kč a větší 450 Kč dávají dohromady 750 Kč a poměr 300 : 450 se zkrátí na 2 : 3.',badcheck:'Stačí ověřit, že větší díl přesahuje polovinu z 750 Kč.',model:'Čísla 2 a 3 určují počet stejně velkých dílů, nikoli přímo koruny.',modelChoice:{q:'Kolik stejných dílů představuje celá výhra?',a:['5 dílů','3 díly'],ok:0},practice:{q:'Který zlomek celku tvoří větší díl?',a:['3/5','3/2'],ok:0}},
  {title:'Rozdělení nákladu na tři díly',story:['Tři sourozenci si rozdělí 400 kg brambor z rodinné zahrady v poměru 2 : 3 : 5.','Chceme znát podíl prostředního sourozence (tři díly poměru).'],question:'Kolik kilogramů brambor dostane prostřední sourozenec?',other:'Kolik kilogramů dostane sourozenec s nejmenším dílem?',paths:['Sečtu všechny díly poměru (2+3+5=10), určím hodnotu jednoho dílu a vezmu tři díly.','Zapíšu prostřední podíl jako 3/10 z celého množství 400 kg.','Čtyři sta kilogramů vydělím třemi díly poměru rovnou.'],valid:[0,1],explain:['Poměr má 2+3+5=10 dílů. Jeden díl je 400 ÷ 10 = 40 kg a tři díly jsou 120 kg.','Prostřední podíl tvoří tři z deseti stejných dílů: 400 × 3/10 = 120 kg.','Číslo 3 není počet všech dílů poměru; dělení jen třemi by ignorovalo díly ostatních dvou sourozenců.'],answer:120,unit:'kg',check:'Tři díly po 40 kg dávají dohromady 120 kg a všech deset dílů dává celkových 400 kg.',badcheck:'Stačí ověřit, že prostřední díl je menší než 400 kg.',model:'Čísla 2, 3 a 5 určují počet stejně velkých dílů; jejich součet dává celkový počet dílů celku.',modelChoice:{q:'Kolik stejných dílů představuje celých 400 kg?',a:['10 dílů','5 dílů'],ok:0},practice:{q:'Který zlomek celku tvoří prostřední díl?',a:['3/10','3/5'],ok:0}},
  {title:'Vzdálenost na plánu budovy',story:['Plán budovy je nakreslen v měřítku 1 : 50.','Na plánu měří chodba 8 centimetrů.'],question:'Kolik metrů měří chodba ve skutečnosti?',other:'Kolik centimetrů by na plánu měřila chodba dlouhá 6 metrů ve skutečnosti?',paths:['Vynásobím 8 číslem 50 a výsledek v centimetrech převedu na metry.','Zjistím, že 1 cm na plánu představuje 50 cm skutečnosti, a násobím 8 × 50.','Osm centimetrů vydělím číslem 50.'],valid:[0,1],explain:['Skutečná délka je 8 × 50 = 400 cm, tedy 4 metry.','Jeden centimetr na plánu je 50 cm skutečnosti. Osm centimetrů představuje 400 cm = 4 m.','Měřítko říká, kolikrát je skutečnost větší než plán, proto se násobí, ne dělí.'],answer:4,unit:'m',check:'Jeden metr by na plánu měřil 2 cm; 4 metry proto odpovídají 8 cm.',badcheck:'Výsledek je správný, pokud obsahuje stejné číslo 8 jako délka na plánu.',model:'Zápis 1 : 50 znamená, že jeden centimetr na plánu odpovídá 50 centimetrům ve skutečnosti.',modelChoice:{q:'Je skutečná délka větší, nebo menší než délka na plánu?',a:['Je 50krát větší ve stejných jednotkách.','Je 50krát menší.'],ok:0},practice:{q:'Na kolik metrů se převede 400 cm?',a:['4 m','40 m'],ok:0}},
  {title:'Zvětšení fotografie',story:['Původní fotografie má rozměry 15 cm × 10 cm.','Fotografii zvětšujeme v poměru stran 1 : 3.'],question:'Kolik centimetrů bude měřit šířka zvětšené fotografie (rozměr 15 cm)?',other:'Kolik centimetrů bude měřit výška zvětšené fotografie (rozměr 10 cm)?',paths:['Vynásobím původní šířku 15 cm poměrem zvětšení 3.','Použiji poměr 1 : 3 jako podíl nového a starého rozměru: nová šířka = 15 × 3.','K původní šířce 15 cm přičtu číslo 3.'],valid:[0,1],explain:['Nová šířka je 15 × 3 = 45 cm.','Poměr 1 : 3 znamená, že nový rozměr je třikrát větší než původní: 15 × 3 = 45 cm.','Zvětšení v poměru znamená násobení, ne přičítání čísla 3.'],answer:45,unit:'cm',check:'Poměr původní a nové šířky 15 : 45 se zkrátí přesně na 1 : 3, stejně jako zadané zvětšení.',badcheck:'Výsledek je správný, pokud je jen o 3 cm větší než původní šířka.',model:'Při zvětšení v poměru 1 : n se každý rozměr násobí stejným číslem n, aby zůstal zachován tvar obrázku.',modelChoice:{q:'Čím musíme vynásobit původní rozměr při zvětšení v poměru 1 : 3?',a:['Číslem 3.','Přičíst číslo 3.'],ok:0},practice:{q:'Který zápis určí novou šířku?',a:['15 × 3','15 + 3'],ok:0}},
  {title:'Chlapci a dívky ve třídě',story:['Ve třídě je poměr chlapců a dívek 4 : 5.','Třída má celkem 27 žáků.'],question:'Kolik dívek je ve třídě?',other:'Kolik chlapců je ve třídě?',paths:['Sečtu díly poměru (4+5=9), určím hodnotu jednoho dílu a vezmu pět dílů.','Zapíšu počet dívek jako 5/9 z celého počtu 27 žáků.','Sedmadvacet žáků vydělím číslem 5.'],valid:[0,1],explain:['Poměr má 4+5=9 dílů. Jeden díl je 27 ÷ 9 = 3 žáci a pět dílů je 15 dívek.','Dívky tvoří pět z devíti stejných dílů: 27 × 5/9 = 15.','Dělení 27 ÷ 5 nedává celé číslo a neodpovídá správnému postupu podle poměru.'],answer:15,unit:'dívek',check:'Patnáct dívek a dvanáct chlapců dává dohromady 27 žáků a poměr 12 : 15 se zkrátí na 4 : 5.',badcheck:'Stačí ověřit, že dívek je více než chlapců.',model:'Čísla 4 a 5 určují počet stejně velkých dílů, nikoli přímo počet žáků.',modelChoice:{q:'Kolik stejných dílů představuje celá třída?',a:['9 dílů','5 dílů'],ok:0},practice:{q:'Který zlomek celku tvoří dívky?',a:['5/9','5/4'],ok:0}},
  {title:'Poměr surovin v receptu',story:['Recept na těsto míchá mouku a cukr v poměru 5 : 2.','Použijeme 750 gramů mouky.'],question:'Kolik gramů cukru podle receptu potřebujeme?',other:'Kolik gramů mouky a cukru dohromady recept použije?',paths:['Zjistím, kolik gramů připadá na jeden díl poměru (750 ÷ 5), a vynásobím dvěma díly cukru.','Zapíšu poměr jako rovnost zlomků 5/2 = 750/x a vyřeším pro x.','Od množství mouky 750 g odečtu rozdíl poměru 5 − 2 = 3.'],valid:[0,1],explain:['Jeden díl je 750 ÷ 5 = 150 g. Cukr má dva díly, tedy 2 × 150 = 300 g.','Řešením rovnosti poměrů 5/2 = 750/x vyjde x = 300 g, stejný výsledek.','Rozdíl čísel poměru 5 − 2 = 3 nepopisuje množství cukru v gramech.'],answer:300,unit:'g',check:'Poměr mouky a cukru 750 : 300 se zkrátí na 5 : 2, což odpovídá receptu.',badcheck:'Stačí ověřit, že cukru je méně než mouky.',model:'Poměr 5 : 2 rozděluje obě suroviny na díly stejné velikosti; jeden díl zjistíme z množství mouky.',modelChoice:{q:'Kolik dílů poměru připadá na mouku?',a:['5 dílů','2 díly'],ok:0},practice:{q:'Který výpočet určí množství cukru?',a:['(750 ÷ 5) × 2','750 − 5 + 2'],ok:0}},
  {title:'Zmenšený model budovy',story:['Model budovy je zmenšen v poměru 1 : 20 oproti skutečnosti.','Skutečná budova je vysoká 60 metrů.'],question:'Kolik metrů bude vysoký model budovy?',other:'Kolikrát je skutečná budova vyšší než model?',paths:['Vydělím skutečnou výšku 60 m číslem 20.','Uvědomím si, že model je 20krát menší, a vypočítám 60 ÷ 20.','Vynásobím skutečnou výšku 60 m číslem 20.'],valid:[0,1],explain:['Výška modelu je 60 ÷ 20 = 3 m.','Model je 20krát menší než skutečnost, proto se skutečná výška dělí dvaceti: 60 ÷ 20 = 3 m.','Násobení dvaceti by model naopak dvacetkrát zvětšilo, což odporuje zadanému zmenšení.'],answer:3,unit:'m',check:'Model vysoký 3 m vynásobený dvaceti dá zpět skutečnou výšku 60 m.',badcheck:'Výsledek je správný, pokud je větší než skutečná výška.',model:'Zápis 1 : 20 znamená, že skutečnost je dvacetkrát větší než model; model tedy získáme dělením.',modelChoice:{q:'Je model větší, nebo menší než skutečná budova?',a:['Je 20krát menší.','Je 20krát větší.'],ok:0},practice:{q:'Který výpočet určí výšku modelu?',a:['60 ÷ 20','60 × 20'],ok:0}},
  {title:'Strany obdélníku v poměru',story:['Obdélníková zahrada má strany v poměru délka : šířka = 3 : 2.','Obvod zahrady měří 50 metrů.'],question:'Kolik metrů měří delší strana (délka) zahrady?',other:'Kolik metrů měří kratší strana (šířka) zahrady?',paths:['Šířku označím 2x, délku 3x, sestavím rovnici pro obvod 2(2x + 3x) = 50 a vyřeším x, potom vezmu 3x.','Zjistím, že poloviční obvod (délka + šířka) je 25 m, a rozdělím ho v poměru 3 : 2 na pět dílů.','Obvod 50 m rovnou vydělím číslem 3.'],valid:[0,1],explain:['Rovnice 10x = 50 dá x = 5. Délka je 3x = 15 m.','Poloviční obvod 25 m rozdělený v poměru 3 : 2 na pět dílů dává jeden díl 5 m; délka má tři díly, tedy 15 m.','Dělení celého obvodu jen číslem 3 ignoruje, že obvod obsahuje dvě délky i dvě šířky dohromady.'],answer:15,unit:'m',check:'Délka 15 m a šířka 10 m dávají obvod 2 × (15 + 10) = 50 m, což souhlasí se zadáním.',badcheck:'Stačí ověřit, že délka je větší než šířka.',model:'Obvod obdélníku obsahuje dvě délky a dvě šířky; poloviční obvod je součet jedné délky a jedné šířky, který lze rozdělit podle daného poměru.',modelChoice:{q:'Co představuje poloviční obvod (25 m)?',a:['Součet jedné délky a jedné šířky.','Jen samotnou délku.'],ok:0},practice:{q:'Která rovnice odpovídá zadání?',a:['2(2x + 3x) = 50','2x + 3x = 50'],ok:0}},
  {title:'Rozdělení zisku podle vkladu',story:['Dva společníci si rozdělí roční zisk firmy 12 000 Kč v poměru svých vkladů 3 : 7.','Větší podíl náleží společníkovi se sedmi díly poměru.'],question:'Kolik korun dostane společník s větším podílem?',other:'Kolik korun dostane společník s menším podílem?',paths:['Sečtu díly poměru (3+7=10), určím hodnotu jednoho dílu a vezmu sedm dílů.','Zapíšu větší podíl jako 7/10 z celého zisku 12 000 Kč.','Zisk 12 000 Kč vydělím větším číslem poměru 7.'],valid:[0,1],explain:['Poměr má 3+7=10 dílů. Jeden díl je 12 000 ÷ 10 = 1 200 Kč a sedm dílů je 8 400 Kč.','Větší podíl tvoří sedm z deseti stejných dílů: 12 000 × 7/10 = 8 400 Kč.','Číslo 7 není počet všech dílů poměru; dělení jen sedmi by nezachovalo celkový součet zisku.'],answer:8400,unit:'Kč',check:'Menší podíl 3 600 Kč a větší 8 400 Kč dávají dohromady 12 000 Kč a poměr 3 600 : 8 400 se zkrátí na 3 : 7.',badcheck:'Stačí ověřit, že větší podíl přesahuje polovinu zisku.',model:'Čísla 3 a 7 určují počet stejně velkých dílů zisku podle výše vkladu, nikoli přímo koruny.',modelChoice:{q:'Kolik stejných dílů představuje celý zisk?',a:['10 dílů','7 dílů'],ok:0},practice:{q:'Který zlomek celku tvoří větší podíl?',a:['7/10','7/3'],ok:0}},
  {title:'Míchání barvy',story:['Modrou a bílou barvu mícháme v poměru 1 : 4.','Chceme namíchat 15 litrů výsledné barvy.'],question:'Kolik litrů modré barvy použijeme?',other:'Kolik litrů bílé barvy použijeme?',paths:['Celých 15 litrů rozdělím na 1 + 4 dílů a vezmu jeden díl modré barvy.','Zapíšu podíl modré barvy jako 1/5 z celkového objemu.','Objem 15 litrů vydělím číslem 4.'],valid:[0,1],explain:['Pět dílů představuje 15 litrů, jeden díl jsou 3 litry. Modrá barva má jeden díl, tedy 3 litry.','Modrá barva tvoří jeden z pěti dílů směsi: 15 × 1/5 = 3 litry.','Číslo 4 označuje jen díly bílé barvy, nikoli všechny díly směsi.'],answer:3,unit:'l',check:'Tři litry modré a dvanáct litrů bílé barvy dají 15 litrů a poměr 3 : 12 se zkrátí na 1 : 4.',badcheck:'Výsledek je správný, pokud je modré barvy více než bílé.',model:'Poměr 1 : 4 rozděluje celou směs na pět stejně velkých dílů.',modelChoice:{q:'Kolik stejných dílů představuje celá namíchaná barva?',a:['5 dílů','4 díly'],ok:0},practice:{q:'Kolik litrů připadá na jeden díl poměru?',a:['15 ÷ 5','15 ÷ 4'],ok:0}}
 ];
