 const slozeneContent=[
  {title:'Vklad na účet v mínusu',story:['Bankovní účet je v mínusu 450 Kč.','Majitel na účet vloží částku, která představuje 120 % dluhu.'],question:'Kolik korun bude na účtu po vkladu?',other:'Kolik korun majitel na účet vložil?',paths:['Nejprve vypočítám vklad jako 120 % z 450 Kč, potom ho přičtu k zápornému zůstatku −450.','Zjistím vklad 450 × 1,2 = 540 Kč a sečtu −450 + 540.','Vklad vypočítám jako 120 % z 450 Kč, ale výsledný zůstatek nechám záporný.'],valid:[0,1],explain:['Vklad je 450 × 1,2 = 540 Kč; nový zůstatek je −450 + 540 = 90 Kč.','Postup krok za krokem vede ke stejnému výsledku 90 Kč.','Vklad převyšuje dluh (120 % > 100 %), proto musí být nový zůstatek kladný, ne záporný.'],answer:90,unit:'Kč',check:'Vklad 540 Kč je o 90 Kč vyšší než dluh 450 Kč, proto zůstatek po vkladu je kladných 90 Kč.',badcheck:'Výsledek je správný, pokud zůstane záporný.',model:'Úloha nejprve pomocí procent zjistí výši vkladu, a teprve potom ho sečte se záporným zůstatkem účtu.',modelChoice:{q:'Je vklad 120 % dluhu vyšší, nebo nižší než samotný dluh?',a:['Vyšší, protože 120 % je víc než 100 %.','Nižší, protože 120 % je míň než 100 %.'],ok:0},practice:{q:'Který výpočet určí nový zůstatek?',a:['−450 + (450 × 1,2)','−450 + 450'],ok:0}},
  {title:'Rozdělení naplněné nádrže',story:['Nádrž o objemu 80 litrů je naplněná ze 3/4.','Naplněný obsah chceme rozdělit do dvou nádob v poměru 2 : 3.'],question:'Kolik litrů dostane nádoba s větším podílem (tři díly poměru)?',other:'Kolik litrů je v nádrži aktuálně napuštěno?',paths:['Nejprve zjistím naplněný obsah (80 × 3/4), potom ho rozdělím v poměru 2 : 3 a vezmu větší podíl.','Vypočítám naplněný obsah 60 litrů a z něj vezmu 3/5 (větší podíl v poměru 2 : 3).','Rozdělím celý objem nádrže 80 litrů v poměru 2 : 3 bez ohledu na to, kolik je aktuálně napuštěno.'],valid:[0,1],explain:['Naplněný obsah je 80 × 3/4 = 60 litrů. Větší podíl je 60 × 3/5 = 36 litrů.','Postup krok za krokem vede ke stejnému výsledku 36 litrů.','Poměr se má rozdělit z aktuálně napuštěných 60 litrů, ne z celého objemu nádrže 80 litrů.'],answer:36,unit:'l',check:'Menší podíl 24 litrů a větší 36 litrů dávají dohromady 60 litrů, což je naplněný obsah nádrže.',badcheck:'Výsledek je správný, pokud je roven celému objemu nádrže.',model:'Úloha má dva kroky: nejprve zlomek určí skutečně napuštěné množství, teprve to se pak dělí v daném poměru.',modelChoice:{q:'Co musíme zjistit jako první?',a:['Kolik litrů je aktuálně v nádrži napuštěno.','Rovnou větší podíl z celého objemu nádrže.'],ok:0},practice:{q:'Který výpočet určí naplněný obsah?',a:['80 × 3/4','80 × 2/3'],ok:0}},
  {title:'Recept pro více osob se sladidlem navíc',story:['Recept pro 4 osoby potřebuje 250 gramů cukru.','Chceme připravit porci pro 10 osob a navíc přidat 10 % cukru pro sladší chuť.'],question:'Kolik gramů cukru celkem použijeme?',other:'Kolik gramů cukru by recept potřeboval pro 10 osob bez přidání navíc?',paths:['Nejprve přepočítám množství cukru na 10 osob (250 ÷ 4 × 10), potom k němu přičtu 10 % navíc.','Vypočítám množství pro 10 osob 625 g a vynásobím ho číslem 1,1.','Rovnou vynásobím 250 gramů číslem 1,1 a poté přepočítám na 10 osob.'],valid:[0,1],explain:['Množství pro 10 osob je 250 ÷ 4 × 10 = 625 g; s desetiprocentním přídavkem je to 625 × 1,1 = 687,5 g.','Postup krok za krokem vede ke stejnému výsledku 687,5 g.','Přepočet na osoby musí proběhnout dřív, aby dávalo smysl navyšovat množství pro celou desetičlennou porci, ne jen původní čtyřčlennou.'],answer:687.5,unit:'g',check:'Šest set osmdesát sedm a půl gramu je o 10 % více než množství pro 10 osob bez přídavku (625 g).',badcheck:'Výsledek je správný, pokud je menší než 625 g.',model:'Úloha spojuje přímou úměrnost (přepočet na počet osob) s procentním navýšením výsledného množství.',modelChoice:{q:'Kolik gramů cukru by recept potřeboval pro 10 osob bez přídavku?',a:['625 g.','250 g.'],ok:0},practice:{q:'Který výpočet určí celkové množství cukru?',a:['(250 ÷ 4 × 10) × 1,1','250 × 1,1'],ok:0}},
  {title:'Zahrada s jezírkem',story:['Obdélníková zahrada má rozměry 20 m × 15 m.','Uvnitř zahrady je trojúhelníkové jezírko se základnou 6 m a výškou 4 m, které se do užitné plochy nepočítá.'],question:'Kolik metrů čtverečních zahrady zbývá mimo jezírko?',other:'Kolik metrů čtverečních má samotné jezírko?',paths:['Vypočítám obsah celé zahrady a odečtu od něj obsah trojúhelníkového jezírka.','Nejprve spočítám obsah obdélníku 300 m² a obsah trojúhelníku 12 m², potom je odečtu.','Odečtu od rozměrů zahrady rozměry jezírka a vynásobím zmenšené rozměry.'],valid:[0,1],explain:['Obsah zahrady je 20 × 15 = 300 m², obsah jezírka 6 × 4 ÷ 2 = 12 m². Rozdíl je 300 − 12 = 288 m².','Postup krok za krokem vede ke stejnému výsledku 288 m².','Odečtení rozměrů jezírka od rozměrů zahrady před násobením (14 × 11) neodpovídá skutečnému tvaru ani umístění jezírka.'],answer:288,unit:'m²',check:'Užitná plocha 288 m² plus jezírko 12 m² dá dohromady celou zahradu 300 m².',badcheck:'Výsledek je správný, pokud je roven celé ploše zahrady.',model:'Obsah složeného pozemku se počítá odečtením obsahu výřezu (jezírka) od obsahu celého obdélníku.',modelChoice:{q:'Co musíme od obsahu zahrady odečíst?',a:['Obsah trojúhelníkového jezírka.','Obvod trojúhelníkového jezírka.'],ok:0},practice:{q:'Který výpočet určí užitnou plochu?',a:['20 × 15 − 6 × 4 ÷ 2','(20 − 6) × (15 − 4)'],ok:0}},
  {title:'Posun bodu po souměrnosti',story:['Bod G má souřadnice [−8; 5].','Nejprve bod překlopíme středovou souměrností podle počátku, a k x-ové souřadnici vzniklého obrazu potom přičteme číslo −3.'],question:'Jaká je konečná x-ová souřadnice bodu po obou úpravách?',other:'Jaká je y-ová souřadnice obrazu po středové souměrnosti?',paths:['Nejprve najdu obraz středové souměrnosti [8; −5], a k jeho x-ové souřadnici přičtu −3.','Provedu oba kroky postupně ve správném pořadí: nejprve souměrnost, potom přičtení čísla.','Rovnou přičtu −3 k původní souřadnici −8 a souměrnost zcela vynechám.'],valid:[0,1],explain:['Obraz středové souměrnosti je [8; −5]; po přičtení −3 k x-ové souřadnici je výsledek 8 + (−3) = 5.','Postup krok za krokem vede ke stejnému výsledku 5.','Vynechání středové souměrnosti by dalo úplně jiný výsledek −11, který neodpovídá zadanému pořadí kroků.'],answer:5,unit:'',check:'Obraz středové souměrnosti [8; −5] má x-ovou souřadnici 8; po přičtení −3 vznikne 5, což je menší než 8, jak má být po přičtení záporného čísla.',badcheck:'Výsledek je správný, pokud je roven původní x-ové souřadnici −8.',model:'Úloha má dva na sebe navazující kroky: nejprve geometrickou transformaci (souměrnost), teprve potom aritmetickou úpravu souřadnice.',modelChoice:{q:'Jakou x-ovou souřadnici má obraz bodu G po středové souměrnosti podle počátku?',a:['8','−8'],ok:0},practice:{q:'Který výpočet určí konečnou x-ovou souřadnici?',a:['8 + (−3)','−8 + (−3)'],ok:0}},
  {title:'Rozdělení útraty bratry',story:['Dva bratři si rozdělí společnou útratu 156,80 Kč v poměru 3 : 5.','Větší díl připadne tomu, komu náleží pět dílů poměru.'],question:'Kolik korun zaplatí bratr s větším podílem?',other:'Kolik korun zaplatí bratr s menším podílem?',paths:['Sečtu díly poměru (3+5=8), určím hodnotu jednoho dílu (156,80 ÷ 8) a vezmu pět dílů.','Zapíšu větší podíl jako 5/8 z celé částky 156,80 Kč.','Částku 156,80 Kč vydělím větším číslem poměru 5.'],valid:[0,1],explain:['Jeden díl je 156,80 ÷ 8 = 19,60 Kč; pět dílů je 5 × 19,60 = 98 Kč.','Větší podíl tvoří pět z osmi stejných dílů: 156,80 × 5/8 = 98 Kč.','Dělení jen pěti (156,80 ÷ 5 = 31,36) neodpovídá správnému postupu podle poměru, protože ignoruje, že celá částka se dělí na osm dílů.'],answer:98,unit:'Kč',check:'Menší díl 58,80 Kč a větší 98 Kč dávají dohromady 156,80 Kč a poměr 58,80 : 98 se zkrátí na 3 : 5.',badcheck:'Stačí ověřit, že větší díl přesahuje polovinu z 156,80 Kč.',model:'Čísla 3 a 5 určují počet stejně velkých dílů, nikoli přímo koruny; hodnotu jednoho dílu musíme nejprve zjistit dělením celé částky.',modelChoice:{q:'Kolik stejných dílů představuje celá útrata?',a:['8 dílů','5 dílů'],ok:0},practice:{q:'Který zlomek celku tvoří větší díl?',a:['5/8','5/3'],ok:0}},
  {title:'Podíl chlapců ve třídě',story:['Ve třídě je 32 žáků.','Dívky tvoří 3/8 všech žáků třídy.'],question:'Kolik procent žáků třídy jsou chlapci?',other:'Kolik žáků jsou dívky?',paths:['Nejprve zjistím počet dívek (32 × 3/8 = 12), potom počet chlapců (32 − 12 = 20) a jejich procentní podíl (20 ÷ 32 × 100).','Zjistím, že dívky tvoří 3/8 (37,5 %) žáků, a chlapci proto tvoří zbylých 100 % − 37,5 % = 62,5 %.','Vydělím počet dívek 12 celkovým počtem žáků 32 a výsledek prohlásím za podíl chlapců.'],valid:[0,1],explain:['Dívek je 12, chlapců 32 − 12 = 20; podíl chlapců je 20 ÷ 32 × 100 = 62,5 %.','Zlomek 3/8 odpovídá 37,5 %; doplněk do 100 % je 62,5 %, stejný výsledek.','Podíl 12 ÷ 32 × 100 = 37,5 % je procento DÍVEK, ne chlapců, na které se ptá otázka.'],answer:62.5,unit:'%',check:'Součet podílu dívek (37,5 %) a chlapců (62,5 %) dává dohromady 100 % všech žáků třídy.',badcheck:'Výsledek je správný, pokud je roven procentu dívek.',model:'Úloha nejprve pomocí zlomku zjistí počet dívek, a teprve z doplňku do celku určí procentní podíl chlapců.',modelChoice:{q:'Jak zjistíme procentní podíl chlapců, když známe podíl dívek?',a:['Odečteme podíl dívek od 100 %.','Vydělíme podíl dívek dvěma.'],ok:0},practice:{q:'Který výpočet určí procento chlapců?',a:['(32 − 32×3/8) ÷ 32 × 100','32×3/8 ÷ 32 × 100'],ok:0}},
  {title:'Zvětšený model vlajky',story:['Model trojúhelníkové vlajky má obsah 15 centimetrů čtverečních.','Skutečná vlajka je zvětšená v poměru stran 1 : 4 oproti modelu.'],question:'Kolik centimetrů čtverečních bude mít obsah skutečné vlajky?',other:'Kolikrát delší budou strany skutečné vlajky oproti modelu?',paths:['Uvědomím si, že obsah se při zvětšení stran v poměru 1 : 4 zvětší 4² = 16krát, a vynásobím 15 × 16.','Vyzkouším konkrétní rozměry modelu, zvětším je čtyřikrát a porovnám nové a původní obsahy — poměr obsahů vyjde 16 : 1.','Obsah zvětším jen čtyřikrát, stejně jako strany.'],valid:[0,1],explain:['Obsah zvětšený 16krát je 15 × 16 = 240 cm².','Konkrétní příklad (např. základna 6 cm, výška 5 cm, obsah 15 cm²; po zvětšení 24 cm a 20 cm, obsah 240 cm²) potvrzuje poměr obsahů 16 : 1.','Obsah není přímo úměrný straně — závisí na druhé mocnině poměru zvětšení, proto se nezvětší jen čtyřikrát jako strany.'],answer:240,unit:'cm²',check:'Poměr nového a starého obsahu 240 : 15 se zkrátí na 16 : 1, což odpovídá druhé mocnině poměru stran 4² = 16.',badcheck:'Výsledek je správný, pokud je roven jen čtyřnásobku původního obsahu (60 cm²).',model:'Obsah rovinného útvaru závisí na druhé mocnině poměru zvětšení stran, proto se při n-násobném zvětšení stran obsah zvětší n²-krát.',modelChoice:{q:'Kolikrát se zvětší obsah, když se strany zvětší 4krát?',a:['16krát (4²).','4krát.'],ok:0},practice:{q:'Který výpočet určí nový obsah?',a:['15 × 4²','15 × 4'],ok:0}},
  {title:'Cena benzínu na trase',story:['Auto má spotřebu 6,5 litru benzinu na 100 kilometrů.','Ujedeme trasu dlouhou 340 kilometrů a litr benzinu stojí 36,80 Kč.'],question:'Kolik korun stojí benzin spotřebovaný na celou trasu (zaokrouhleno na setiny)?',other:'Kolik litrů benzinu auto na trase spotřebuje?',paths:['Nejprve vypočítám spotřebu na celou trasu (340 ÷ 100 × 6,5) a potom ji vynásobím cenou 36,80 Kč.','Zjistím spotřebu 22,1 litru a vynásobím ji cenou za litr.','Vynásobím délku trasy 340 km přímo cenou litru 36,80 Kč.'],valid:[0,1],explain:['Spotřeba je 3,4 × 6,5 = 22,1 litru. Cena je 22,1 × 36,80 = 813,28 Kč.','Postup krok za krokem vede ke stejnému výsledku 813,28 Kč.','Kilometry nelze násobit přímo cenou litru; mezi nimi musíme nejprve použít údaj o spotřebě.'],answer:813.28,unit:'Kč',check:'Cena 813,28 Kč dělená 36,80 Kč za litr dává spotřebu 22,1 litru, která odpovídá 340 km.',badcheck:'Výsledek je správný, pokud je nižší než cena jednoho litru.',model:'Řešení má dva kroky: kilometry nejprve převedeme pomocí spotřeby na litry, a litry pomocí ceny na koruny.',modelChoice:{q:'Kterou meziveličinu musíme zjistit před cenou?',a:['Počet spotřebovaných litrů.','Počet hodin jízdy.'],ok:0},practice:{q:'Který výpočet určí spotřebu na trase?',a:['340 ÷ 100 × 6,5','340 × 36,80'],ok:0}},
  {title:'Nárůst teploty o násobek',story:['Ranní teplota byla −8 °C.','Do poledne teplota stoupla o hodnotu, která je 1,5násobkem absolutní hodnoty ranní teploty (tedy 1,5 × 8 °C).'],question:'Kolik stupňů Celsia bylo v poledne?',other:'O kolik stupňů teplota stoupla?',paths:['Nejprve vypočítám nárůst (1,5 × 8 = 12 °C), potom ho přičtu k ranní teplotě −8 °C.','Zjistím nárůst 12 °C a sečtu −8 + 12.','Vynásobím ranní teplotu −8 přímo číslem 1,5 a považuji výsledek za teplotu v poledne.'],valid:[0,1],explain:['Nárůst je 1,5 × 8 = 12 °C; teplota v poledne je −8 + 12 = 4 °C.','Postup krok za krokem vede ke stejnému výsledku 4 °C.','Násobení celé ranní teploty (−8 × 1,5 = −12) by odpovídalo jiné otázce, ne nárůstu vypočtenému z absolutní hodnoty.'],answer:4,unit:'°C',check:'Nárůst 12 °C přičtený k ranní teplotě −8 °C dá poledních 4 °C, což je vyšší hodnota, jak zadání očekává.',badcheck:'Výsledek je správný, pokud je záporný.',model:'Nárůst teploty se počítá z absolutní hodnoty (velikosti bez znaménka) ranní teploty, a teprve tento nárůst se přičítá k původní (záporné) teplotě.',modelChoice:{q:'Z jaké hodnoty počítáme 1,5násobek pro nárůst teploty?',a:['Z absolutní hodnoty 8, bez znaménka.','Přímo ze záporné teploty −8.'],ok:0},practice:{q:'Který výpočet určí teplotu v poledne?',a:['−8 + (1,5 × 8)','−8 × 1,5'],ok:0}}
 ];
